#!/usr/bin/env node
/**
 * ============================================================================
 * Teacher's Activity Bank — Automated Project Manager Upgrade Script (v2.0)
 * ============================================================================
 * Usage:
 *   Place this file in your project root (`teachers-activity-bank/`) and run:
 *   node apply-pm-upgrades.mjs
 *
 * What this script does automatically:
 *   1. Upgrades Prisma Schema & SQL Triggers/Policies to support 5 Roles:
 *      (INSTITUTION, INSPECTOR, TEACHER, STUDENT, ADMIN).
 *   2. Fixes Backend resilience in worksheet.service.ts & /api/auth/me.
 *   3. Adds Global Theme (Light/Dark Mode) & Trilingual (AR/FR/EN) Context.
 *   4. Replaces the cluttered Navbar with a clean 2-button Auth bar + Theme + Language.
 *   5. Adds the Full-Screen 4-Option Role Selection Modal (AuthRoleModal.tsx).
 *   6. Upgrades /login and /register pages with full 4-role selection & dynamic fields.
 * ============================================================================
 */

import fs from "fs";
import path from "path";

const files = {
  "tailwind.config.ts": "import type { Config } from \"tailwindcss\";\n\nconst config: Config = {\n  darkMode: \"class\",\n  content: [\n    \"./src/pages/**/*.{js,ts,jsx,tsx,mdx}\",\n    \"./src/components/**/*.{js,ts,jsx,tsx,mdx}\",\n    \"./src/context/**/*.{js,ts,jsx,tsx,mdx}\",\n    \"./src/app/**/*.{js,ts,jsx,tsx,mdx}\",\n  ],\n  theme: {\n    extend: {\n      fontFamily: {\n        cairo: [\"var(--font-cairo)\", \"sans-serif\"],\n      },\n      colors: {\n        primary: {\n          50: \"#eff6ff\",\n          100: \"#dbeafe\",\n          200: \"#bfdbfe\",\n          300: \"#93c5fd\",\n          400: \"#60a5fa\",\n          500: \"#3b82f6\",\n          600: \"#2563eb\",\n          700: \"#1d4ed8\",\n          800: \"#1e40af\",\n          900: \"#1e3a8a\",\n        },\n      },\n    },\n  },\n  plugins: [],\n};\n\nexport default config;\n",
  "prisma/schema.prisma": "// ============================================================\n// Teacher's Activity Bank — Prisma Schema (Upgraded v2.0)\n// بنك أنشطة المعلم — يدعم المؤسسات، المتفقدين، المعلمين، التلاميذ، والمشرفين\n// ============================================================\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  previewFeatures = [\"fullTextSearchPostgres\"]\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ── Enums ────────────────────────────────────────────────────\n\nenum Role {\n  INSTITUTION\n  INSPECTOR\n  TEACHER\n  STUDENT\n  ADMIN\n}\n\nenum WorksheetStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n// ── Models ───────────────────────────────────────────────────\n\nmodel User {\n  id               String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  email            String   @unique @db.VarChar(255)\n  name             String   @db.VarChar(255)\n  avatarUrl        String?  @map(\"avatar_url\") @db.Text\n  role             Role     @default(TEACHER)\n  school           String?  @db.VarChar(255) // المدرسة، المؤسسة التربوية، أو الدائرة التفقدية\n  inspectorPending Boolean  @default(false) @map(\"inspector_pending\")\n  inspectorCode    String?  @unique @map(\"inspector_code\") @db.VarChar(32)\n  createdAt        DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt        DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  // Relations\n  worksheets Worksheet[]\n  downloads  Download[]\n  favorites  Favorite[]\n  reviews    Review[]\n\n  @@map(\"users\")\n}\n\nmodel Category {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"categories\")\n}\n\nmodel Grade {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"grades\")\n}\n\nmodel Subject {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  color     String?  @db.VarChar(7)\n  icon      String?  @db.VarChar(50)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"subjects\")\n}\n\nmodel Worksheet {\n  id            String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title         String          @db.VarChar(255)\n  titleAr       String?         @map(\"title_ar\") @db.VarChar(255)\n  description   String?         @db.Text\n  descriptionAr String?         @map(\"description_ar\") @db.Text\n  categoryId    String          @map(\"category_id\") @db.Uuid\n  gradeId       String          @map(\"grade_id\") @db.Uuid\n  subjectId     String          @map(\"subject_id\") @db.Uuid\n  uploadedBy    String          @map(\"uploaded_by\") @db.Uuid\n  fileUrl       String          @map(\"file_url\") @db.Text\n  fileName      String          @map(\"file_name\") @db.VarChar(255)\n  fileSize      Int             @map(\"file_size\")\n  thumbnailUrl  String?         @map(\"thumbnail_url\") @db.Text\n  pageCount     Int?            @map(\"page_count\")\n  status        WorksheetStatus @default(DRAFT)\n  tags          String[]        @default([])\n  downloadCount Int             @default(0) @map(\"download_count\")\n  favoriteCount Int             @default(0) @map(\"favorite_count\")\n  ratingAvg     Float           @default(0) @map(\"rating_avg\")\n  reviewCount   Int             @default(0) @map(\"review_count\")\n  createdAt     DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt     DateTime        @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  category  Category   @relation(fields: [categoryId], references: [id])\n  grade     Grade      @relation(fields: [gradeId], references: [id])\n  subject   Subject    @relation(fields: [subjectId], references: [id])\n  uploader  User       @relation(fields: [uploadedBy], references: [id])\n  downloads Download[]\n  favorites Favorite[]\n  reviews   Review[]\n\n  @@index([status])\n  @@index([gradeId])\n  @@index([subjectId])\n  @@index([categoryId])\n  @@index([uploadedBy])\n  @@index([createdAt(sort: Desc)])\n  @@index([gradeId, subjectId])\n  @@map(\"worksheets\")\n}\n\nmodel Download {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId       String   @map(\"user_id\") @db.Uuid\n  worksheetId  String   @map(\"worksheet_id\") @db.Uuid\n  downloadedAt DateTime @default(now()) @map(\"downloaded_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([userId])\n  @@map(\"downloads\")\n}\n\nmodel Favorite {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId      String   @map(\"user_id\") @db.Uuid\n  worksheetId String   @map(\"worksheet_id\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([userId])\n  @@map(\"favorites\")\n}\n\nmodel Review {\n  id                  String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  rating              Int\n  comment             String   @db.Text\n  isOfficialDirective Boolean  @default(false) @map(\"is_official_directive\")\n  userId              String   @map(\"user_id\") @db.Uuid\n  worksheetId         String   @map(\"worksheet_id\") @db.Uuid\n  createdAt           DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt           DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([worksheetId])\n  @@index([userId])\n  @@map(\"reviews\")\n}\n",
  "supabase/sql/triggers.sql": "-- ============================================================\n-- Database Triggers (Upgraded v2.0 — Multi-Role Aware)\n-- Teacher's Activity Bank\n-- ============================================================\n-- Security: Maps requested role safely.\n-- INSTITUTION, TEACHER, STUDENT are assigned directly.\n-- INSPECTOR registrations start as TEACHER with inspector_pending = true\n-- until verified via single-use activation code (INSP-XXXX-XXXX).\n-- ADMIN is strictly blocked from self-registration.\n-- ============================================================\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER AS $$\nDECLARE\n  raw_role TEXT;\n  assigned_role public.\"Role\";\n  is_insp_pending BOOLEAN;\nBEGIN\n  raw_role := UPPER(COALESCE(NEW.raw_user_meta_data ->> 'role', 'TEACHER'));\n  is_insp_pending := COALESCE((NEW.raw_user_meta_data ->> 'inspector_pending')::boolean, false);\n\n  IF raw_role = 'INSTITUTION' THEN\n    assigned_role := 'INSTITUTION'::public.\"Role\";\n  ELSIF raw_role = 'STUDENT' THEN\n    assigned_role := 'STUDENT'::public.\"Role\";\n  ELSIF raw_role = 'INSPECTOR' THEN\n    -- Inspector requires secret activation code; stays TEACHER with pending flag until activated\n    assigned_role := 'TEACHER'::public.\"Role\";\n    is_insp_pending := true;\n  ELSE\n    assigned_role := 'TEACHER'::public.\"Role\";\n  END IF;\n\n  INSERT INTO public.users (id, email, name, school, avatar_url, inspector_pending, role, created_at, updated_at)\n  VALUES (\n    NEW.id,\n    NEW.email,\n    COALESCE(NEW.raw_user_meta_data ->> 'name', split_part(NEW.email, '@', 1)),\n    NEW.raw_user_meta_data ->> 'school',\n    NEW.raw_user_meta_data ->> 'avatar_url',\n    is_insp_pending,\n    assigned_role,\n    NOW(),\n    NOW()\n  )\n  ON CONFLICT (id) DO UPDATE SET\n    name = EXCLUDED.name,\n    school = COALESCE(EXCLUDED.school, public.users.school),\n    avatar_url = COALESCE(EXCLUDED.avatar_url, public.users.avatar_url),\n    inspector_pending = EXCLUDED.inspector_pending;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW\n  EXECUTE FUNCTION public.handle_new_user();\n\n-- ── Updated_at auto-update trigger ──────────────────────────\n\nCREATE OR REPLACE FUNCTION public.update_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS set_updated_at_users ON users;\nCREATE TRIGGER set_updated_at_users\n  BEFORE UPDATE ON users\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at();\n\nDROP TRIGGER IF EXISTS set_updated_at_worksheets ON worksheets;\nCREATE TRIGGER set_updated_at_worksheets\n  BEFORE UPDATE ON worksheets\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at();\n",
  "supabase/sql/rls-policies.sql": "-- ============================================================\n-- Row Level Security (RLS) Policies (Cleaned & Idempotent v2.0)\n-- Teacher's Activity Bank\n-- ============================================================\n\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\nALTER TABLE worksheets ENABLE ROW LEVEL SECURITY;\nALTER TABLE downloads ENABLE ROW LEVEL SECURITY;\nALTER TABLE favorites ENABLE ROW LEVEL SECURITY;\nALTER TABLE reviews ENABLE ROW LEVEL SECURITY;\nALTER TABLE categories ENABLE ROW LEVEL SECURITY;\nALTER TABLE grades ENABLE ROW LEVEL SECURITY;\nALTER TABLE subjects ENABLE ROW LEVEL SECURITY;\n\n-- ── Users ────────────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Users can view own profile\" ON users;\nCREATE POLICY \"Users can view own profile\"\n  ON users FOR SELECT\n  USING (auth.uid() = id);\n\nDROP POLICY IF EXISTS \"Users can update own profile\" ON users;\nCREATE POLICY \"Users can update own profile\"\n  ON users FOR UPDATE\n  USING (auth.uid() = id);\n\nDROP POLICY IF EXISTS \"Service role full access to users\" ON users;\nCREATE POLICY \"Service role full access to users\"\n  ON users FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Worksheets ───────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view published worksheets\" ON worksheets;\nCREATE POLICY \"Anyone can view published worksheets\"\n  ON worksheets FOR SELECT\n  USING (status = 'PUBLISHED');\n\nDROP POLICY IF EXISTS \"Users can view own worksheets\" ON worksheets;\nCREATE POLICY \"Users can view own worksheets\"\n  ON worksheets FOR SELECT\n  USING (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Authenticated users can create worksheets\" ON worksheets;\nCREATE POLICY \"Authenticated users can create worksheets\"\n  ON worksheets FOR INSERT\n  WITH CHECK (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Users can update own worksheets\" ON worksheets;\nCREATE POLICY \"Users can update own worksheets\"\n  ON worksheets FOR UPDATE\n  USING (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Service role full access to worksheets\" ON worksheets;\nCREATE POLICY \"Service role full access to worksheets\"\n  ON worksheets FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Downloads ────────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Users can view own downloads\" ON downloads;\nCREATE POLICY \"Users can view own downloads\"\n  ON downloads FOR SELECT\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to downloads\" ON downloads;\nCREATE POLICY \"Service role full access to downloads\"\n  ON downloads FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Favorites ────────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Users can view own favorites\" ON favorites;\nCREATE POLICY \"Users can view own favorites\"\n  ON favorites FOR SELECT\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to favorites\" ON favorites;\nCREATE POLICY \"Service role full access to favorites\"\n  ON favorites FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Reviews ──────────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view reviews\" ON reviews;\nCREATE POLICY \"Anyone can view reviews\"\n  ON reviews FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Authenticated users can create own reviews\" ON reviews;\nCREATE POLICY \"Authenticated users can create own reviews\"\n  ON reviews FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Users can update own reviews\" ON reviews;\nCREATE POLICY \"Users can update own reviews\"\n  ON reviews FOR UPDATE\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Users can delete own reviews\" ON reviews;\nCREATE POLICY \"Users can delete own reviews\"\n  ON reviews FOR DELETE\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to reviews\" ON reviews;\nCREATE POLICY \"Service role full access to reviews\"\n  ON reviews FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Reference Tables (public read) ──────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view categories\" ON categories;\nCREATE POLICY \"Anyone can view categories\"\n  ON categories FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Anyone can view grades\" ON grades;\nCREATE POLICY \"Anyone can view grades\"\n  ON grades FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Anyone can view subjects\" ON subjects;\nCREATE POLICY \"Anyone can view subjects\"\n  ON subjects FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Service role full access to categories\" ON categories;\nCREATE POLICY \"Service role full access to categories\"\n  ON categories FOR ALL\n  USING (auth.role() = 'service_role');\n\nDROP POLICY IF EXISTS \"Service role full access to grades\" ON grades;\nCREATE POLICY \"Service role full access to grades\"\n  ON grades FOR ALL\n  USING (auth.role() = 'service_role');\n\nDROP POLICY IF EXISTS \"Service role full access to subjects\" ON subjects;\nCREATE POLICY \"Service role full access to subjects\"\n  ON subjects FOR ALL\n  USING (auth.role() = 'service_role');\n",
  "src/types/api.ts": "/**\n * API Contracts and Data Transfer Object (DTO) Type Definitions (Upgraded v2.0)\n */\n\nexport type Role = \"INSTITUTION\" | \"INSPECTOR\" | \"TEACHER\" | \"STUDENT\" | \"ADMIN\";\nexport type AccountRoleOption = \"INSTITUTION\" | \"INSPECTOR\" | \"TEACHER\" | \"STUDENT\";\nexport type WorksheetStatus = \"DRAFT\" | \"PUBLISHED\" | \"ARCHIVED\";\n\nexport type WorksheetSortOption = \"newest\" | \"popular\" | \"downloads\" | \"title\";\n\nexport interface PaginationMeta {\n  page: number;\n  limit: number;\n  total: number;\n  totalPages: number;\n}\n\nexport interface ApiSuccessResponse<T> {\n  success: true;\n  data: T;\n  meta?: PaginationMeta;\n}\n\nexport interface ApiErrorDetail {\n  field?: string;\n  message: string;\n}\n\nexport interface ApiErrorResponse {\n  success: false;\n  error: {\n    code: string;\n    message: string;\n    details?: ApiErrorDetail[];\n  };\n}\n\nexport type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;\n\nexport interface User {\n  id: string;\n  email: string;\n  name: string;\n  avatarUrl: string | null;\n  role: Role;\n  school: string | null;\n  inspectorPending?: boolean;\n  inspectorCode?: string | null;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface Category {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Grade {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Subject {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  color: string | null;\n  icon: string | null;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Worksheet {\n  id: string;\n  title: string;\n  titleAr: string | null;\n  description: string | null;\n  descriptionAr: string | null;\n  categoryId: string;\n  gradeId: string;\n  subjectId: string;\n  uploadedBy: string;\n  fileUrl: string;\n  fileName: string;\n  fileSize: number;\n  thumbnailUrl: string | null;\n  pageCount: number | null;\n  status: WorksheetStatus;\n  tags: string[];\n  downloadCount: number;\n  favoriteCount: number;\n  ratingAvg: number;\n  reviewCount: number;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface WorksheetWithRelations extends Worksheet {\n  category: Category;\n  grade: Grade;\n  subject: Subject;\n  uploader: Pick<User, \"id\" | \"name\" | \"avatarUrl\" | \"school\" | \"role\">;\n  previewUrl?: string;\n}\n\nexport interface WorksheetFilterParams {\n  page?: number;\n  limit?: number;\n  search?: string;\n  grade?: string;\n  subject?: string;\n  category?: string;\n  tags?: string[];\n  sort?: WorksheetSortOption;\n  status?: WorksheetStatus;\n}\n\nexport interface Download {\n  id: string;\n  userId: string;\n  worksheetId: string;\n  downloadedAt: Date | string;\n}\n\nexport interface Favorite {\n  id: string;\n  userId: string;\n  worksheetId: string;\n  createdAt: Date | string;\n}\n\nexport interface Review {\n  id: string;\n  rating: number;\n  comment: string;\n  isOfficialDirective: boolean;\n  userId: string;\n  worksheetId: string;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface ReviewWithUser extends Review {\n  user: Pick<User, \"id\" | \"name\" | \"avatarUrl\" | \"school\" | \"role\">;\n}\n",
  "src/lib/validators/auth.ts": "/**\n * Auth Validation Schemas (Upgraded v2.0 — Supports 4 Account Types)\n */\n\nimport { z } from \"zod\";\n\nexport const accountRoleOptionSchema = z\n  .enum([\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"])\n  .default(\"TEACHER\");\n\n/** Email/password sign-up */\nexport const signUpSchema = z.object({\n  email: z.string().email(\"البريد الإلكتروني غير صالح / Invalid email\"),\n  password: z\n    .string()\n    .min(8, \"كلمة المرور يجب ألا تقل عن 8 أحرف / Min 8 characters\")\n    .max(72, \"كلمة المرور طويلة جداً\"),\n  name: z\n    .string()\n    .trim()\n    .min(2, \"الاسم يجب أن يتكون من حرفين على الأقل\")\n    .max(255, \"الاسم طويل جداً\"),\n  school: z.string().trim().max(255).optional(),\n  role: accountRoleOptionSchema.optional().default(\"TEACHER\"),\n});\n\n/** Email/password sign-in */\nexport const signInSchema = z.object({\n  email: z.string().email(\"البريد الإلكتروني غير صالح / Invalid email\"),\n  password: z.string().min(1, \"كلمة المرور مطلوبة / Password is required\"),\n  role: accountRoleOptionSchema.optional(),\n});\n\n/** Profile update */\nexport const updateProfileSchema = z.object({\n  name: z\n    .string()\n    .trim()\n    .min(2, \"الاسم يجب أن يتكون من حرفين على الأقل\")\n    .max(255)\n    .optional(),\n  school: z.string().trim().max(255).optional(),\n  avatarUrl: z.string().url(\"رابط الصورة غير صالح\").optional().nullable(),\n});\n\nexport type SignUpInput = z.infer<typeof signUpSchema>;\nexport type SignInInput = z.infer<typeof signInSchema>;\nexport type UpdateProfileInput = z.infer<typeof updateProfileSchema>;\n",
  "src/services/worksheet.service.ts": "/**\n * Worksheet Service (Upgraded v2.0 — Resilient Preview & Dynamic Thumbnail Signing)\n */\n\nimport { db } from \"@/lib/db\";\nimport { Prisma, WorksheetStatus } from \"@prisma/client\";\nimport { getPaginationParams, buildPaginationMeta } from \"@/lib/utils/pagination\";\nimport { NotFoundError, ForbiddenError } from \"@/lib/utils/errors\";\nimport { getSignedDownloadUrl } from \"@/services/storage.service\";\nimport type { WorksheetFilterInput, CreateWorksheetInput, UpdateWorksheetInput } from \"@/lib/validators/worksheet\";\n\nexport const publicWorksheetSelect = {\n  id: true,\n  title: true,\n  titleAr: true,\n  description: true,\n  descriptionAr: true,\n  categoryId: true,\n  gradeId: true,\n  subjectId: true,\n  uploadedBy: true,\n  fileUrl: true,\n  fileName: true,\n  fileSize: true,\n  thumbnailUrl: true,\n  pageCount: true,\n  status: true,\n  tags: true,\n  downloadCount: true,\n  favoriteCount: true,\n  ratingAvg: true,\n  reviewCount: true,\n  createdAt: true,\n  updatedAt: true,\n  category: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      sortOrder: true,\n    },\n  },\n  grade: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      sortOrder: true,\n    },\n  },\n  subject: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      color: true,\n      icon: true,\n      sortOrder: true,\n    },\n  },\n  uploader: {\n    select: {\n      id: true,\n      name: true,\n      avatarUrl: true,\n      school: true,\n      role: true,\n    },\n  },\n} as const;\n\nexport async function listWorksheets(filters: WorksheetFilterInput) {\n  const { page, limit, search, grade, subject, category, tags, sort } = filters;\n  const { skip, take, page: currentPage, limit: currentLimit } = getPaginationParams(page, limit);\n\n  const where: Prisma.WorksheetWhereInput = {\n    status: WorksheetStatus.PUBLISHED,\n  };\n\n  if (grade) where.grade = { slug: grade };\n  if (subject) where.subject = { slug: subject };\n  if (category) where.category = { slug: category };\n  if (tags && tags.length > 0) where.tags = { hasSome: tags };\n\n  if (search && search.trim().length > 0) {\n    const term = search.trim();\n    where.OR = [\n      { title: { contains: term, mode: \"insensitive\" } },\n      { titleAr: { contains: term, mode: \"insensitive\" } },\n      { description: { contains: term, mode: \"insensitive\" } },\n      { descriptionAr: { contains: term, mode: \"insensitive\" } },\n      { tags: { has: term } },\n    ];\n  }\n\n  const orderBy: Prisma.WorksheetOrderByWithRelationInput = (() => {\n    switch (sort) {\n      case \"popular\":\n        return { favoriteCount: \"desc\" };\n      case \"downloads\":\n        return { downloadCount: \"desc\" };\n      case \"title\":\n        return { title: \"asc\" };\n      case \"newest\":\n      default:\n        return { createdAt: \"desc\" };\n    }\n  })();\n\n  const [total, worksheets] = await Promise.all([\n    db.worksheet.count({ where }),\n    db.worksheet.findMany({\n      where,\n      select: publicWorksheetSelect,\n      orderBy,\n      skip,\n      take,\n    }),\n  ]);\n\n  return {\n    data: worksheets,\n    meta: buildPaginationMeta(total, currentPage, currentLimit),\n  };\n}\n\n/**\n * Retrieves a single worksheet by unique ID with resilient preview URL generation.\n * Fix: If Supabase Storage is unreachable or file preview fails, does NOT crash the whole page.\n */\nexport async function getWorksheetById(id: string) {\n  const worksheet = await db.worksheet.findUnique({\n    where: { id },\n    select: publicWorksheetSelect,\n  });\n\n  if (!worksheet || worksheet.status === WorksheetStatus.ARCHIVED) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  let previewUrl: string | undefined = undefined;\n  try {\n    previewUrl = await getSignedDownloadUrl(worksheet.fileUrl, 3600);\n  } catch (err) {\n    console.warn(\"[getWorksheetById] Preview signed URL fallback:\", err);\n  }\n\n  return {\n    ...worksheet,\n    previewUrl,\n  };\n}\n\nexport interface CreateWorksheetData extends CreateWorksheetInput {\n  uploadedBy: string;\n  fileUrl: string;\n  fileName: string;\n  fileSize: number;\n  thumbnailUrl?: string;\n  pageCount?: number;\n}\n\nexport async function createWorksheet(data: CreateWorksheetData) {\n  return db.worksheet.create({\n    data: {\n      title: data.title,\n      titleAr: data.titleAr ?? null,\n      description: data.description ?? null,\n      descriptionAr: data.descriptionAr ?? null,\n      categoryId: data.categoryId,\n      gradeId: data.gradeId,\n      subjectId: data.subjectId,\n      uploadedBy: data.uploadedBy,\n      fileUrl: data.fileUrl,\n      fileName: data.fileName,\n      fileSize: data.fileSize,\n      thumbnailUrl: data.thumbnailUrl ?? null,\n      pageCount: data.pageCount ?? null,\n      tags: data.tags ?? [],\n      status: WorksheetStatus.PUBLISHED,\n    },\n    select: publicWorksheetSelect,\n  });\n}\n\nexport async function updateWorksheet(\n  id: string,\n  userId: string,\n  data: UpdateWorksheetInput,\n  userRole?: string\n) {\n  const existing = await db.worksheet.findUnique({\n    where: { id },\n    select: { id: true, uploadedBy: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  if (existing.uploadedBy !== userId && userRole !== \"ADMIN\") {\n    throw new ForbiddenError(\"You can only edit your own worksheets\");\n  }\n\n  return db.worksheet.update({\n    where: { id },\n    data: {\n      ...(data.title !== undefined ? { title: data.title } : {}),\n      ...(data.titleAr !== undefined ? { titleAr: data.titleAr } : {}),\n      ...(data.description !== undefined ? { description: data.description } : {}),\n      ...(data.descriptionAr !== undefined ? { descriptionAr: data.descriptionAr } : {}),\n      ...(data.categoryId !== undefined ? { categoryId: data.categoryId } : {}),\n      ...(data.gradeId !== undefined ? { gradeId: data.gradeId } : {}),\n      ...(data.subjectId !== undefined ? { subjectId: data.subjectId } : {}),\n      ...(data.tags !== undefined ? { tags: data.tags } : {}),\n      ...(data.status !== undefined ? { status: data.status } : {}),\n    },\n    select: publicWorksheetSelect,\n  });\n}\n\nexport async function archiveWorksheet(\n  id: string,\n  userId: string,\n  userRole?: string\n) {\n  const existing = await db.worksheet.findUnique({\n    where: { id },\n    select: { id: true, uploadedBy: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  if (existing.uploadedBy !== userId && userRole !== \"ADMIN\") {\n    throw new ForbiddenError(\"You can only archive your own worksheets\");\n  }\n\n  await db.worksheet.update({\n    where: { id },\n    data: { status: WorksheetStatus.ARCHIVED },\n  });\n\n  return { success: true, archived: true, id };\n}\n\nexport async function getUserUploads(userId: string, pageInput?: number, limitInput?: number) {\n  const { skip, take, page, limit } = getPaginationParams(pageInput, limitInput);\n\n  const where: Prisma.WorksheetWhereInput = {\n    uploadedBy: userId,\n    status: { not: WorksheetStatus.ARCHIVED },\n  };\n\n  const [total, worksheets] = await Promise.all([\n    db.worksheet.count({ where }),\n    db.worksheet.findMany({\n      where,\n      select: publicWorksheetSelect,\n      orderBy: { createdAt: \"desc\" },\n      skip,\n      take,\n    }),\n  ]);\n\n  return {\n    data: worksheets,\n    meta: buildPaginationMeta(total, page, limit),\n  };\n}\n",
  "src/app/api/auth/me/route.ts": "import { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { db } from \"@/lib/db\";\nimport { successResponse, errorResponse } from \"@/lib/utils/api-response\";\nimport { UnauthorizedError } from \"@/lib/utils/errors\";\nimport { Role } from \"@prisma/client\";\n\nexport async function GET() {\n  try {\n    const supabase = await createSupabaseServerClient();\n    const {\n      data: { user },\n    } = await supabase.auth.getUser();\n\n    if (!user) {\n      throw new UnauthorizedError(\"Not authenticated\");\n    }\n\n    let profile = await db.user.findUnique({\n      where: { id: user.id },\n      include: {\n        _count: {\n          select: {\n            worksheets: true,\n            favorites: true,\n            downloads: true,\n          },\n        },\n      },\n    });\n\n    if (!profile) {\n      const rawRole = String(user.user_metadata?.role || \"TEACHER\").toUpperCase();\n      const safeRole: Role =\n        rawRole === \"INSTITUTION\"\n          ? Role.INSTITUTION\n          : rawRole === \"STUDENT\"\n          ? Role.STUDENT\n          : Role.TEACHER;\n\n      const isInspectorPending =\n        Boolean(user.user_metadata?.inspector_pending) || rawRole === \"INSPECTOR\";\n\n      profile = await db.user.create({\n        data: {\n          id: user.id,\n          email: user.email!,\n          name: (user.user_metadata?.name as string) || user.email!.split(\"@\")[0],\n          school: (user.user_metadata?.school as string) || null,\n          role: safeRole,\n          inspectorPending: isInspectorPending,\n        },\n        include: {\n          _count: {\n            select: {\n              worksheets: true,\n              favorites: true,\n              downloads: true,\n            },\n          },\n        },\n      });\n    }\n\n    // Exclude sensitive inspectorCode to prevent leaking the secret activation code to the client\n    const { inspectorCode: _inspectorCode, ...safeProfile } = profile;\n    return successResponse(safeProfile);\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n",
  "src/components/ui/InspectorBadge.tsx": "import React from \"react\";\nimport { BadgeCheck, Building2, GraduationCap } from \"lucide-react\";\nimport type { Role } from \"@/types\";\n\ninterface InspectorBadgeProps {\n  role?: Role | string;\n  size?: \"sm\" | \"md\";\n}\n\nexport default function InspectorBadge({ role, size = \"sm\" }: InspectorBadgeProps) {\n  if (role === \"INSPECTOR\") {\n    return (\n      <span\n        title=\"متفقد تربوي معتمد تم التحقق من هويته من قِبل الإدارة\"\n        className={`inline-flex items-center gap-1 rounded-full bg-gradient-to-r from-amber-500 to-amber-600 text-white font-bold shadow-sm select-none ${\n          size === \"sm\" ? \"px-2 py-0.5 text-[10px]\" : \"px-3 py-1 text-xs\"\n        }`}\n      >\n        <BadgeCheck className={size === \"sm\" ? \"w-3 h-3\" : \"w-4 h-4\"} />\n        <span>متفقد معتمد</span>\n      </span>\n    );\n  }\n\n  if (role === \"INSTITUTION\") {\n    return (\n      <span\n        title=\"مؤسسة تربوية مسجلة\"\n        className={`inline-flex items-center gap-1 rounded-full bg-gradient-to-r from-indigo-600 to-violet-600 text-white font-bold shadow-sm select-none ${\n          size === \"sm\" ? \"px-2 py-0.5 text-[10px]\" : \"px-3 py-1 text-xs\"\n        }`}\n      >\n        <Building2 className={size === \"sm\" ? \"w-3 h-3\" : \"w-4 h-4\"} />\n        <span>مؤسسة تربوية</span>\n      </span>\n    );\n  }\n\n  if (role === \"STUDENT\") {\n    return (\n      <span\n        title=\"حساب تلميذ\"\n        className={`inline-flex items-center gap-1 rounded-full bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800 font-bold select-none ${\n          size === \"sm\" ? \"px-2 py-0.5 text-[10px]\" : \"px-3 py-1 text-xs\"\n        }`}\n      >\n        <GraduationCap className={size === \"sm\" ? \"w-3 h-3\" : \"w-4 h-4\"} />\n        <span>تلميذ</span>\n      </span>\n    );\n  }\n\n  return null;\n}\n",
  "src/context/AppPreferencesContext.tsx": "\"use client\";\n\n/**\n * Global Theme (Light / Dark) & Trilingual (AR / FR / EN) Preferences Context\n *\n * Automatically persists user theme and language choices to localStorage,\n * toggles the `dark` class on `<html>`, and switches `dir=\"rtl\" | \"ltr\"` and `lang`.\n */\n\nimport React, { createContext, useContext, useState, useEffect } from \"react\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nexport type Locale = \"ar\" | \"fr\" | \"en\";\nexport type ThemeMode = \"light\" | \"dark\";\n\nexport interface RoleMetadataTranslations {\n  title: string;\n  subtitle: string;\n  badge: string;\n  orgLabel: string;\n  orgPlaceholder: string;\n  nameLabel: string;\n  namePlaceholder: string;\n}\n\nexport interface Dictionary {\n  dir: \"rtl\" | \"ltr\";\n  brandName: string;\n  brandTagline: string;\n  nav: {\n    home: string;\n    browse: string;\n    upload: string;\n    adminPanel: string;\n    login: string;\n    register: string;\n    logout: string;\n    profile: string;\n    themeLight: string;\n    themeDark: string;\n    language: string;\n  };\n  authModal: {\n    loginTitle: string;\n    loginSubtitle: string;\n    registerTitle: string;\n    registerSubtitle: string;\n    switchToRegister: string;\n    switchToLogin: string;\n    close: string;\n    continueBtn: string;\n    changeRoleBtn: string;\n  };\n  roles: Record<AccountRoleOption, RoleMetadataTranslations>;\n  authForm: {\n    emailLabel: string;\n    passwordLabel: string;\n    passwordHint: string;\n    submitLogin: string;\n    submitRegister: string;\n    googleContinue: string;\n    orDivider: string;\n    inspectorNote: string;\n    haveCodeQuestion: string;\n    activateCodeLink: string;\n  };\n}\n\nexport const DICTIONARIES: Record<Locale, Dictionary> = {\n  ar: {\n    dir: \"rtl\",\n    brandName: \"بنك أنشطة المعلم\",\n    brandTagline: \"منصة التعليم الابتدائي\",\n    nav: {\n      home: \"الرئيسية\",\n      browse: \"تصفح الأنشطة\",\n      upload: \"رفع نشاط\",\n      adminPanel: \"لوحة المشرف\",\n      login: \"تسجيل الدخول\",\n      register: \"إنشاء حساب\",\n      logout: \"خروج\",\n      profile: \"الملف الشخصي\",\n      themeLight: \"الوضع النهاري\",\n      themeDark: \"الوضع الليلي\",\n      language: \"اللغة\",\n    },\n    authModal: {\n      loginTitle: \"اختر نوع الحساب لتسجيل الدخول\",\n      loginSubtitle: \"حدد صفتك التربوية للوصول المباشر إلى فضائك الخاص في المنصة\",\n      registerTitle: \"اختر نوع الحساب الذي تريد إنشاءه\",\n      registerSubtitle: \"أنشئ حساباً مخصصاً يناسب دورك في المنظومة التربوية\",\n      switchToRegister: \"ليس لديك حساب؟ انتقل إلى إنشاء حساب جديد\",\n      switchToLogin: \"لديك حساب بالفعل؟ انتقل إلى تسجيل الدخول\",\n      close: \"إغلاق النافذة\",\n      continueBtn: \"متابعة\",\n      changeRoleBtn: \"تغيير نوع الحساب\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"حساب مؤسسة تربوية\",\n        subtitle: \"للمدارس الابتدائية، المعاهد، والمؤسسات التعليمية لإدارة ومشاركة مكتبة الأنشطة المدرسية.\",\n        badge: \"الاختيار الأول • مؤسسة\",\n        orgLabel: \"اسم المؤسسة التربوية / المدرسة *\",\n        orgPlaceholder: \"مثال: المدرسة الابتدائية حي النور\",\n        nameLabel: \"اسم المدير أو المسؤول التربوي *\",\n        namePlaceholder: \"مثال: أ. عبد الرحمن بن صالح\",\n      },\n      INSPECTOR: {\n        title: \"حساب متفقد تربوي\",\n        subtitle: \"للمتفقدين والموجهين البيداغوجيين لاعتماد الأنشطة وتقديم التوجيهات الرسمية المثبتة.\",\n        badge: \"الاختيار الثاني • متفقد\",\n        orgLabel: \"الدائرة التفقدية / المندوبية الجهوية *\",\n        orgPlaceholder: \"مثال: دائرة التفقد التربوي بقفصة\",\n        nameLabel: \"الاسم الكامل للمتفقد *\",\n        namePlaceholder: \"مثال: د. محمد الهادي\",\n      },\n      TEACHER: {\n        title: \"حساب معلم\",\n        subtitle: \"لمعلمي ومعلمات المرحلة الابتدائية لرفع أوراق العمل، تحميل الموارد، وتبادل الخبرات.\",\n        badge: \"الاختيار الثالث • معلم\",\n        orgLabel: \"المدرسة التي تدرّس بها (اختياري)\",\n        orgPlaceholder: \"مثال: مدرسة الأمل الابتدائية\",\n        nameLabel: \"الاسم الكامل للمعلم *\",\n        namePlaceholder: \"مثال: أ. سارة المنصوري\",\n      },\n      STUDENT: {\n        title: \"حساب تلميذ\",\n        subtitle: \"للتلاميذ وأولياء الأمور لتصفح وتحميل أوراق العمل، الاختبارات، والأنشطة التفاعلية مجاناً.\",\n        badge: \"الاختيار الرابع • تلميذ\",\n        orgLabel: \"المدرسة / الصف الدراسي (اختياري)\",\n        orgPlaceholder: \"مثال: الصف الخامس ابتدائي\",\n        nameLabel: \"اسم التلميذ *\",\n        namePlaceholder: \"مثال: ياسين التونسي\",\n      },\n    },\n    authForm: {\n      emailLabel: \"البريد الإلكتروني *\",\n      passwordLabel: \"كلمة المرور *\",\n      passwordHint: \"8 أحرف على الأقل\",\n      submitLogin: \"تسجيل الدخول الآن\",\n      submitRegister: \"إنشاء الحساب الآن\",\n      googleContinue: \"المتابعة باستخدام حساب Google\",\n      orDivider: \"أو\",\n      inspectorNote: \"ملاحظة للمتفقدين: بعد إنشاء الحساب، يمنحك المشرف العام كود التفعيل لتوثيق الشارة الذهبية.\",\n      haveCodeQuestion: \"هل لديك كود تفعيل متفقد؟\",\n      activateCodeLink: \"تفعيل الكود الآن\",\n    },\n  },\n\n  fr: {\n    dir: \"ltr\",\n    brandName: \"Banque d'Activités\",\n    brandTagline: \"Plateforme de l'Enseignement Primaire\",\n    nav: {\n      home: \"Accueil\",\n      browse: \"Parcourir\",\n      upload: \"Publier\",\n      adminPanel: \"Administration\",\n      login: \"Connexion\",\n      register: \"Créer un compte\",\n      logout: \"Déconnexion\",\n      profile: \"Mon Profil\",\n      themeLight: \"Mode Clair\",\n      themeDark: \"Mode Sombre\",\n      language: \"Langue\",\n    },\n    authModal: {\n      loginTitle: \"Choisissez votre profil de connexion\",\n      loginSubtitle: \"Sélectionnez votre espace dédié pour accéder rapidement à vos outils pédagogiques\",\n      registerTitle: \"Choisissez le type de compte à créer\",\n      registerSubtitle: \"Rejoignez la plateforme selon votre rôle dans l'écosystème éducatif\",\n      switchToRegister: \"Pas encore de compte ? Créer un nouveau compte\",\n      switchToLogin: \"Déjà inscrit ? Se connecter à mon compte\",\n      close: \"Fermer\",\n      continueBtn: \"Continuer\",\n      changeRoleBtn: \"Changer le type de compte\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"Espace Établissement\",\n        subtitle: \"Pour les écoles primaires et institutions éducatives afin de gérer et partager leurs ressources.\",\n        badge: \"Option 1 • Établissement\",\n        orgLabel: \"Nom de l'établissement scolaire *\",\n        orgPlaceholder: \"Ex: École Primaire Al-Amal\",\n        nameLabel: \"Nom du directeur / responsable *\",\n        namePlaceholder: \"Ex: M. Karim Ben Ali\",\n      },\n      INSPECTOR: {\n        title: \"Espace Inspecteur\",\n        subtitle: \"Pour les inspecteurs pédagogiques afin d'encadrer, certifier et publier des directives officielles.\",\n        badge: \"Option 2 • Inspecteur\",\n        orgLabel: \"Circonscription / Délégation régionale *\",\n        orgPlaceholder: \"Ex: Circonscription pédagogique de Gafsa\",\n        nameLabel: \"Nom complet de l'inspecteur *\",\n        namePlaceholder: \"Ex: Dr. Mohamed Hedi\",\n      },\n      TEACHER: {\n        title: \"Espace Enseignant\",\n        subtitle: \"Pour les enseignants du primaire afin de publier, télécharger et évaluer des fiches d'activités.\",\n        badge: \"Option 3 • Enseignant\",\n        orgLabel: \"École d'affectation (optionnel)\",\n        orgPlaceholder: \"Ex: École Primaire Ibn Khaldoun\",\n        nameLabel: \"Nom complet de l'enseignant *\",\n        namePlaceholder: \"Ex: Mme. Sarra Mansouri\",\n      },\n      STUDENT: {\n        title: \"Espace Élève\",\n        subtitle: \"Pour les élèves et parents afin de réviser et télécharger gratuitement les exercices et examens.\",\n        badge: \"Option 4 • Élève\",\n        orgLabel: \"École / Niveau scolaire (optionnel)\",\n        orgPlaceholder: \"Ex: 5ème année primaire\",\n        nameLabel: \"Nom complet de l'élève *\",\n        namePlaceholder: \"Ex: Yassine Tounsi\",\n      },\n    },\n    authForm: {\n      emailLabel: \"Adresse e-mail *\",\n      passwordLabel: \"Mot de passe *\",\n      passwordHint: \"8 caractères minimum\",\n      submitLogin: \"Se connecter\",\n      submitRegister: \"Créer mon compte\",\n      googleContinue: \"Continuer avec Google\",\n      orDivider: \"OU\",\n      inspectorNote: \"Note aux inspecteurs : Après l'inscription, un code d'activation vous sera fourni par l'administration.\",\n      haveCodeQuestion: \"Vous avez déjà un code inspecteur ?\",\n      activateCodeLink: \"Activer mon code\",\n    },\n  },\n\n  en: {\n    dir: \"ltr\",\n    brandName: \"Teacher's Activity Bank\",\n    brandTagline: \"Primary Education Platform\",\n    nav: {\n      home: \"Home\",\n      browse: \"Browse Catalog\",\n      upload: \"Upload Activity\",\n      adminPanel: \"Admin Panel\",\n      login: \"Log In\",\n      register: \"Sign Up\",\n      logout: \"Sign Out\",\n      profile: \"My Profile\",\n      themeLight: \"Light Mode\",\n      themeDark: \"Dark Mode\",\n      language: \"Language\",\n    },\n    authModal: {\n      loginTitle: \"Select Your Account Type to Log In\",\n      loginSubtitle: \"Choose your educational portal to access your personalized workspace\",\n      registerTitle: \"Select the Account Type to Create\",\n      registerSubtitle: \"Create a tailored account matching your role in the educational community\",\n      switchToRegister: \"Don't have an account? Create a new account\",\n      switchToLogin: \"Already have an account? Log in here\",\n      close: \"Close\",\n      continueBtn: \"Continue\",\n      changeRoleBtn: \"Change Account Type\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"Educational Institution\",\n        subtitle: \"For primary schools and educational centers to curate and share institutional resource banks.\",\n        badge: \"Option 1 • Institution\",\n        orgLabel: \"Official Institution / School Name *\",\n        orgPlaceholder: \"e.g., Al-Noor Primary School\",\n        nameLabel: \"Principal or Coordinator Name *\",\n        namePlaceholder: \"e.g., Mr. Abdulrahman Saleh\",\n      },\n      INSPECTOR: {\n        title: \"Pedagogical Inspector\",\n        subtitle: \"For certified educational inspectors to review worksheets and pin official directives.\",\n        badge: \"Option 2 • Inspector\",\n        orgLabel: \"Inspection District / Regional Directorate *\",\n        orgPlaceholder: \"e.g., Primary Inspection District\",\n        nameLabel: \"Inspector Full Name *\",\n        namePlaceholder: \"e.g., Dr. Mohamed Hedi\",\n      },\n      TEACHER: {\n        title: \"Teacher Account\",\n        subtitle: \"For primary school teachers to upload PDF worksheets, bookmark activities, and collaborate.\",\n        badge: \"Option 3 • Teacher\",\n        orgLabel: \"School Name (Optional)\",\n        orgPlaceholder: \"e.g., Al-Amal Primary School\",\n        nameLabel: \"Teacher Full Name *\",\n        namePlaceholder: \"e.g., Ms. Sara Mansouri\",\n      },\n      STUDENT: {\n        title: \"Student Account\",\n        subtitle: \"For students and parents to browse, preview, and download printable worksheets and quizzes.\",\n        badge: \"Option 4 • Student\",\n        orgLabel: \"School / Grade Level (Optional)\",\n        orgPlaceholder: \"e.g., Grade 5 Primary\",\n        nameLabel: \"Student Full Name *\",\n        namePlaceholder: \"e.g., Yassine Tounsi\",\n      },\n    },\n    authForm: {\n      emailLabel: \"Email Address *\",\n      passwordLabel: \"Password *\",\n      passwordHint: \"At least 8 characters\",\n      submitLogin: \"Log In Now\",\n      submitRegister: \"Create Account\",\n      googleContinue: \"Continue with Google\",\n      orDivider: \"OR\",\n      inspectorNote: \"Inspector Note: After signing up, the administrator will issue your activation code to unlock the verified badge.\",\n      haveCodeQuestion: \"Already have an inspector code?\",\n      activateCodeLink: \"Activate Code\",\n    },\n  },\n};\n\ninterface AppPreferencesContextValue {\n  locale: Locale;\n  setLocale: (loc: Locale) => void;\n  theme: ThemeMode;\n  toggleTheme: () => void;\n  setTheme: (theme: ThemeMode) => void;\n  t: Dictionary;\n  authModalMode: \"login\" | \"register\" | null;\n  openAuthModal: (mode: \"login\" | \"register\") => void;\n  closeAuthModal: () => void;\n}\n\nconst AppPreferencesContext = createContext<AppPreferencesContextValue | undefined>(undefined);\n\nexport function AppPreferencesProvider({ children }: { children: React.ReactNode }) {\n  const [locale, setLocaleState] = useState<Locale>(\"ar\");\n  const [theme, setThemeState] = useState<ThemeMode>(\"light\");\n  const [authModalMode, setAuthModalMode] = useState<\"login\" | \"register\" | null>(null);\n\n  useEffect(() => {\n    try {\n      const savedLocale = localStorage.getItem(\"tab_locale\") as Locale | null;\n      if (savedLocale && (savedLocale === \"ar\" || savedLocale === \"fr\" || savedLocale === \"en\")) {\n        setLocaleState(savedLocale);\n      }\n\n      const savedTheme = localStorage.getItem(\"tab_theme\") as ThemeMode | null;\n      if (savedTheme === \"dark\" || savedTheme === \"light\") {\n        setThemeState(savedTheme);\n      } else if (window.matchMedia(\"(prefers-color-scheme: dark)\").matches) {\n        setThemeState(\"dark\");\n      }\n    } catch {\n      // ignore storage errors\n    }\n  }, []);\n\n  useEffect(() => {\n    const dict = DICTIONARIES[locale];\n    document.documentElement.lang = locale;\n    document.documentElement.dir = dict.dir;\n    document.body.style.direction = dict.dir;\n    document.body.style.textAlign = dict.dir === \"rtl\" ? \"right\" : \"left\";\n    try {\n      localStorage.setItem(\"tab_locale\", locale);\n    } catch {\n      // ignore\n    }\n  }, [locale]);\n\n  useEffect(() => {\n    const root = document.documentElement;\n    if (theme === \"dark\") {\n      root.classList.add(\"dark\");\n    } else {\n      root.classList.remove(\"dark\");\n    }\n    try {\n      localStorage.setItem(\"tab_theme\", theme);\n    } catch {\n      // ignore\n    }\n  }, [theme]);\n\n  const setLocale = (loc: Locale) => setLocaleState(loc);\n  const setTheme = (mode: ThemeMode) => setThemeState(mode);\n  const toggleTheme = () => setThemeState((prev) => (prev === \"light\" ? \"dark\" : \"light\"));\n\n  const openAuthModal = (mode: \"login\" | \"register\") => setAuthModalMode(mode);\n  const closeAuthModal = () => setAuthModalMode(null);\n\n  return (\n    <AppPreferencesContext.Provider\n      value={{\n        locale,\n        setLocale,\n        theme,\n        toggleTheme,\n        setTheme,\n        t: DICTIONARIES[locale],\n        authModalMode,\n        openAuthModal,\n        closeAuthModal,\n      }}\n    >\n      {children}\n    </AppPreferencesContext.Provider>\n  );\n}\n\nexport function useAppPreferences() {\n  const ctx = useContext(AppPreferencesContext);\n  if (!ctx) {\n    throw new Error(\"useAppPreferences must be used inside AppPreferencesProvider\");\n  }\n  return ctx;\n}\n",
  "src/components/auth/AuthRoleModal.tsx": "\"use client\";\n\n/**\n * Full-Screen 4-Option Role Selection Overlay (Modal & Embedded Selector)\n *\n * Implements the exact 4 choices requested by the Project Manager:\n * 1. Institution (مؤسسة تربوية - INSTITUTION)\n * 2. Inspector (متفقد تربوي - INSPECTOR)\n * 3. Teacher (معلم - TEACHER)\n * 4. Student (تلميذ - STUDENT)\n */\n\nimport React, { useEffect } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  Building2,\n  ShieldCheck,\n  BookOpen,\n  GraduationCap,\n  X,\n  ArrowLeft,\n  ArrowRight,\n  Sparkles,\n} from \"lucide-react\";\nimport { useAppPreferences } from \"@/context/AppPreferencesContext\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nexport interface RoleOptionVisual {\n  role: AccountRoleOption;\n  icon: React.ComponentType<{ className?: string }>;\n  gradient: string;\n  borderHover: string;\n  badgeStyle: string;\n  iconBg: string;\n}\n\nexport const ROLE_VISUAL_CARDS: RoleOptionVisual[] = [\n  {\n    role: \"INSTITUTION\",\n    icon: Building2,\n    gradient: \"from-indigo-600 to-violet-700\",\n    borderHover: \"hover:border-indigo-500 dark:hover:border-indigo-400\",\n    badgeStyle:\n      \"bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300 dark:border-indigo-800\",\n    iconBg: \"bg-indigo-600 text-white shadow-indigo-500/25\",\n  },\n  {\n    role: \"INSPECTOR\",\n    icon: ShieldCheck,\n    gradient: \"from-amber-500 to-orange-600\",\n    borderHover: \"hover:border-amber-500 dark:hover:border-amber-400\",\n    badgeStyle:\n      \"bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/60 dark:text-amber-300 dark:border-amber-800\",\n    iconBg: \"bg-gradient-to-br from-amber-500 to-amber-600 text-white shadow-amber-500/25\",\n  },\n  {\n    role: \"TEACHER\",\n    icon: BookOpen,\n    gradient: \"from-blue-600 to-cyan-600\",\n    borderHover: \"hover:border-blue-500 dark:hover:border-blue-400\",\n    badgeStyle:\n      \"bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-950/60 dark:text-blue-300 dark:border-blue-800\",\n    iconBg: \"bg-blue-600 text-white shadow-blue-500/25\",\n  },\n  {\n    role: \"STUDENT\",\n    icon: GraduationCap,\n    gradient: \"from-emerald-600 to-teal-600\",\n    borderHover: \"hover:border-emerald-500 dark:hover:border-emerald-400\",\n    badgeStyle:\n      \"bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/60 dark:text-emerald-300 dark:border-emerald-800\",\n    iconBg: \"bg-emerald-600 text-white shadow-emerald-500/25\",\n  },\n];\n\nexport default function AuthRoleModal() {\n  const router = useRouter();\n  const { authModalMode, closeAuthModal, openAuthModal, t } = useAppPreferences();\n\n  // Close on Escape key\n  useEffect(() => {\n    if (!authModalMode) return;\n    const handleKeyDown = (e: KeyboardEvent) => {\n      if (e.key === \"Escape\") closeAuthModal();\n    };\n    window.addEventListener(\"keydown\", handleKeyDown);\n    return () => window.removeEventListener(\"keydown\", handleKeyDown);\n  }, [authModalMode, closeAuthModal]);\n\n  if (!authModalMode) return null;\n\n  const isLogin = authModalMode === \"login\";\n  const ArrowIcon = t.dir === \"rtl\" ? ArrowLeft : ArrowRight;\n\n  const handleSelectRole = (role: AccountRoleOption) => {\n    const targetPath = isLogin ? `/login?role=${role}` : `/register?role=${role}`;\n    closeAuthModal();\n    router.push(targetPath);\n  };\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex flex-col justify-between overflow-y-auto animate-fadeIn p-4 sm:p-8\"\n      dir={t.dir}\n    >\n      {/* Top Bar */}\n      <div className=\"max-w-7xl w-full mx-auto flex items-center justify-between py-2\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center font-black text-xl shadow-lg shadow-blue-500/30\">\n            أ\n          </div>\n          <div>\n            <span className=\"text-lg font-extrabold text-white block leading-none\">\n              {t.brandName}\n            </span>\n            <span className=\"text-xs text-slate-400\">{t.brandTagline}</span>\n          </div>\n        </div>\n\n        <button\n          type=\"button\"\n          onClick={closeAuthModal}\n          className=\"inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-white/10 hover:bg-white/20 text-white text-xs font-bold border border-white/15 transition cursor-pointer\"\n        >\n          <span>{t.authModal.close}</span>\n          <X className=\"w-4 h-4\" />\n        </button>\n      </div>\n\n      {/* Center Content: 4 Full-Screen Proposals */}\n      <div className=\"max-w-7xl w-full mx-auto my-auto py-8 space-y-8\">\n        <div className=\"text-center space-y-3 max-w-2xl mx-auto\">\n          <div className=\"inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-200 text-xs font-bold\">\n            <Sparkles className=\"w-3.5 h-3.5\" />\n            <span>{isLogin ? t.nav.login : t.nav.register}</span>\n          </div>\n          <h2 className=\"text-2xl sm:text-4xl font-black text-white tracking-tight\">\n            {isLogin ? t.authModal.loginTitle : t.authModal.registerTitle}\n          </h2>\n          <p className=\"text-sm sm:text-base text-slate-300 leading-relaxed\">\n            {isLogin ? t.authModal.loginSubtitle : t.authModal.registerSubtitle}\n          </p>\n        </div>\n\n        {/* 4 Cards Grid */}\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5\">\n          {ROLE_VISUAL_CARDS.map((card) => {\n            const Icon = card.icon;\n            const roleText = t.roles[card.role];\n\n            return (\n              <button\n                key={card.role}\n                type=\"button\"\n                onClick={() => handleSelectRole(card.role)}\n                className={`group relative text-start bg-white dark:bg-slate-900 border-2 border-slate-200/90 dark:border-slate-800 ${card.borderHover} rounded-3xl p-6 sm:p-7 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1.5 flex flex-col justify-between cursor-pointer overflow-hidden`}\n              >\n                {/* Top decorative gradient bar */}\n                <div\n                  className={`absolute top-0 inset-x-0 h-2 bg-gradient-to-r ${card.gradient}`}\n                />\n\n                <div className=\"space-y-5 pt-2\">\n                  <div className=\"flex items-center justify-between gap-2\">\n                    <span\n                      className={`px-3 py-1 rounded-full text-[11px] font-extrabold border ${card.badgeStyle}`}\n                    >\n                      {roleText.badge}\n                    </span>\n                    <div\n                      className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg ${card.iconBg} group-hover:scale-110 transition-transform`}\n                    >\n                      <Icon className=\"w-6 h-6\" />\n                    </div>\n                  </div>\n\n                  <div className=\"space-y-2\">\n                    <h3 className=\"text-xl font-black text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors\">\n                      {roleText.title}\n                    </h3>\n                    <p className=\"text-xs sm:text-sm text-slate-600 dark:text-slate-400 leading-relaxed\">\n                      {roleText.subtitle}\n                    </p>\n                  </div>\n                </div>\n\n                <div className=\"pt-6 mt-6 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between text-xs font-extrabold text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400\">\n                  <span>\n                    {isLogin ? t.nav.login : t.nav.register} ({roleText.title})\n                  </span>\n                  <ArrowIcon className=\"w-4 h-4 transform group-hover:translate-x-1 rtl:group-hover:-translate-x-1 transition-transform\" />\n                </div>\n              </button>\n            );\n          })}\n        </div>\n\n        {/* Mode Switcher Footer */}\n        <div className=\"text-center pt-2\">\n          <button\n            type=\"button\"\n            onClick={() => openAuthModal(isLogin ? \"register\" : \"login\")}\n            className=\"text-sm font-bold text-blue-300 hover:text-white underline underline-offset-4 transition cursor-pointer\"\n          >\n            {isLogin ? t.authModal.switchToRegister : t.authModal.switchToLogin}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"text-center text-xs text-slate-500\">\n        © {new Date().getFullYear()} {t.brandName}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/layout/Navbar.tsx": "\"use client\";\n\n/**\n * Upgraded De-Cluttered Responsive Navigation Bar (v2.0)\n *\n * Key Upgrades Implemented per Project Manager Directives:\n * 1. De-cluttered Auth Section: Only TWO clean buttons (\"تسجيل الدخول\" and \"إنشاء حساب\")\n *    when unauthenticated — clicking either opens the Full-Screen 4-Role Selection Overlay.\n * 2. Theme Toggle Button (Light / Dark Mode) with Sun & Moon icons.\n * 3. Language Switcher Dropdown/Pills (العربية AR / Français FR / English EN) with automatic RTL/LTR.\n */\n\nimport React, { useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport {\n  ShieldCheck,\n  Sun,\n  Moon,\n  Globe,\n  LogIn,\n  UserPlus,\n  Upload,\n  Menu,\n  X,\n} from \"lucide-react\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\nimport { createSupabaseBrowserClient } from \"@/lib/supabase/client\";\nimport { useAppPreferences, type Locale } from \"@/context/AppPreferencesContext\";\n\ninterface UserProfile {\n  id: string;\n  name: string;\n  email: string;\n  avatarUrl: string | null;\n  role?: string;\n}\n\nconst LANGUAGES: { code: Locale; label: string; short: string }[] = [\n  { code: \"ar\", label: \"العربية\", short: \"AR\" },\n  { code: \"fr\", label: \"Français\", short: \"FR\" },\n  { code: \"en\", label: \"English\", short: \"EN\" },\n];\n\nexport default function Navbar() {\n  const pathname = usePathname();\n  const router = useRouter();\n  const supabase = createSupabaseBrowserClient();\n  const { locale, setLocale, theme, toggleTheme, t, openAuthModal } = useAppPreferences();\n\n  const [user, setUser] = useState<UserProfile | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);\n  const [langMenuOpen, setLangMenuOpen] = useState(false);\n\n  useEffect(() => {\n    let isMounted = true;\n\n    async function checkUser() {\n      try {\n        const {\n          data: { session },\n        } = await supabase.auth.getSession();\n\n        if (session?.user && isMounted) {\n          const initialUser: UserProfile = {\n            id: session.user.id,\n            name:\n              session.user.user_metadata?.name ||\n              session.user.email?.split(\"@\")[0] ||\n              \"المستخدم\",\n            email: session.user.email || \"\",\n            avatarUrl: session.user.user_metadata?.avatar_url || null,\n          };\n\n          try {\n            const res = await fetch(\"/api/auth/me\", { cache: \"no-store\" });\n            if (res.ok) {\n              const json = await res.json();\n              if (json.success && json.data) {\n                initialUser.role = json.data.role;\n                initialUser.name = json.data.name || initialUser.name;\n                initialUser.avatarUrl = json.data.avatarUrl || initialUser.avatarUrl;\n              }\n            }\n          } catch {\n            // Safe fallback\n          }\n\n          if (isMounted) setUser(initialUser);\n        } else if (isMounted) {\n          setUser(null);\n        }\n      } catch (err) {\n        console.error(\"Auth status error:\", err);\n      } finally {\n        if (isMounted) setLoading(false);\n      }\n    }\n\n    checkUser();\n\n    const {\n      data: { subscription },\n    } = supabase.auth.onAuthStateChange(async (_event, session) => {\n      if (session?.user) {\n        const updatedUser: UserProfile = {\n          id: session.user.id,\n          name:\n            session.user.user_metadata?.name ||\n            session.user.email?.split(\"@\")[0] ||\n            \"المستخدم\",\n          email: session.user.email || \"\",\n          avatarUrl: session.user.user_metadata?.avatar_url || null,\n        };\n\n        try {\n          const res = await fetch(\"/api/auth/me\", { cache: \"no-store\" });\n          if (res.ok) {\n            const json = await res.json();\n            if (json.success && json.data) {\n              updatedUser.role = json.data.role;\n              updatedUser.name = json.data.name || updatedUser.name;\n            }\n          }\n        } catch {\n          // ignore\n        }\n\n        setUser(updatedUser);\n      } else {\n        setUser(null);\n      }\n    });\n\n    return () => {\n      isMounted = false;\n      subscription.unsubscribe();\n    };\n  }, []);\n\n  const handleSignOut = async () => {\n    await supabase.auth.signOut();\n    setUser(null);\n    router.push(\"/login\");\n    router.refresh();\n  };\n\n  const navLinks = [\n    { label: t.nav.home, href: \"/\" },\n    { label: t.nav.browse, href: \"/browse\" },\n  ];\n\n  return (\n    <header className=\"sticky top-0 z-50 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 transition-colors\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n        <div className=\"flex items-center justify-between h-18 py-3 gap-4\">\n          {/* Brand Logo & Primary Navigation */}\n          <div className=\"flex items-center gap-6\">\n            <Link href=\"/\" className=\"flex items-center gap-2.5 group shrink-0\">\n              <div className=\"w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center font-black text-xl shadow-md shadow-blue-500/20 group-hover:scale-105 transition-transform\">\n                أ\n              </div>\n              <div className=\"flex flex-col\">\n                <span className=\"text-lg sm:text-xl font-extrabold text-slate-900 dark:text-white tracking-tight group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors\">\n                  {t.brandName}\n                </span>\n                <span className=\"text-[10px] text-slate-400 dark:text-slate-500 font-medium\">\n                  {t.brandTagline}\n                </span>\n              </div>\n            </Link>\n\n            <nav className=\"hidden lg:flex items-center gap-1\">\n              {navLinks.map((link) => {\n                const isActive = pathname === link.href;\n                return (\n                  <Link\n                    key={link.href}\n                    href={link.href}\n                    className={`px-3.5 py-2 rounded-xl text-sm font-bold transition ${\n                      isActive\n                        ? \"text-blue-600 dark:text-blue-400 bg-blue-50/80 dark:bg-blue-950/50\"\n                        : \"text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800/60\"\n                    }`}\n                  >\n                    {link.label}\n                  </Link>\n                );\n              })}\n            </nav>\n          </div>\n\n          {/* Right/Left Action Area: Theme + Language + De-cluttered Auth */}\n          <div className=\"hidden md:flex items-center gap-2.5\">\n            {/* Language Switcher (AR / FR / EN) */}\n            <div className=\"relative\">\n              <button\n                type=\"button\"\n                onClick={() => setLangMenuOpen((prev) => !prev)}\n                className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-xs font-extrabold text-slate-700 dark:text-slate-200 transition cursor-pointer\"\n                title={t.nav.language}\n              >\n                <Globe className=\"w-4 h-4 text-blue-600 dark:text-blue-400\" />\n                <span>{locale.toUpperCase()}</span>\n              </button>\n\n              {langMenuOpen && (\n                <>\n                  <div\n                    className=\"fixed inset-0 z-10\"\n                    onClick={() => setLangMenuOpen(false)}\n                  />\n                  <div className=\"absolute top-full mt-2 end-0 z-20 w-36 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-xl p-1.5 space-y-1\">\n                    {LANGUAGES.map((lang) => (\n                      <button\n                        key={lang.code}\n                        type=\"button\"\n                        onClick={() => {\n                          setLocale(lang.code);\n                          setLangMenuOpen(false);\n                        }}\n                        className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-bold transition cursor-pointer ${\n                          locale === lang.code\n                            ? \"bg-blue-600 text-white\"\n                            : \"text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800\"\n                        }`}\n                      >\n                        <span>{lang.label}</span>\n                        <span className=\"text-[10px] opacity-80\">{lang.short}</span>\n                      </button>\n                    ))}\n                  </div>\n                </>\n              )}\n            </div>\n\n            {/* Theme Toggle (Light / Dark) */}\n            <button\n              type=\"button\"\n              onClick={toggleTheme}\n              className=\"p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-amber-300 transition cursor-pointer\"\n              title={theme === \"light\" ? t.nav.themeDark : t.nav.themeLight}\n              aria-label=\"Toggle Theme\"\n            >\n              {theme === \"light\" ? (\n                <Moon className=\"w-4 h-4 text-slate-700\" />\n              ) : (\n                <Sun className=\"w-4 h-4 text-amber-400\" />\n              )}\n            </button>\n\n            <div className=\"h-5 w-px bg-slate-200 dark:bg-slate-700 mx-0.5\" />\n\n            {/* Authenticated State vs Clean 2-Button Unauthenticated State */}\n            {!loading && user ? (\n              <div className=\"flex items-center gap-2.5\">\n                <InspectorBadge role={user.role} size=\"md\" />\n\n                {user.role === \"ADMIN\" && (\n                  <Link\n                    href=\"/admin/dashboard\"\n                    className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl bg-purple-50 dark:bg-purple-950/60 hover:bg-purple-100 text-purple-700 dark:text-purple-300 font-bold text-xs border border-purple-200 dark:border-purple-800 transition\"\n                  >\n                    <ShieldCheck className=\"w-4 h-4\" />\n                    <span>{t.nav.adminPanel}</span>\n                  </Link>\n                )}\n\n                {user.role !== \"STUDENT\" && (\n                  <Link\n                    href=\"/upload\"\n                    className=\"flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold px-3.5 py-2.5 rounded-xl shadow-sm transition\"\n                  >\n                    <Upload className=\"w-3.5 h-3.5\" />\n                    <span>{t.nav.upload}</span>\n                  </Link>\n                )}\n\n                <Link\n                  href=\"/profile\"\n                  className=\"flex items-center gap-2 px-2.5 py-1.5 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition border border-transparent hover:border-slate-200 dark:hover:border-slate-700\"\n                >\n                  <div className=\"w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-300 font-bold text-xs flex items-center justify-center\">\n                    {user.name.charAt(0)}\n                  </div>\n                  <span className=\"text-xs font-bold text-slate-800 dark:text-slate-100 max-w-[110px] truncate\">\n                    {user.name}\n                  </span>\n                </Link>\n\n                <button\n                  type=\"button\"\n                  onClick={handleSignOut}\n                  className=\"text-xs font-bold text-slate-500 dark:text-slate-400 hover:text-red-600 px-2.5 py-1.5 rounded-lg hover:bg-red-50 dark:hover:bg-red-950/40 transition cursor-pointer\"\n                >\n                  {t.nav.logout}\n                </button>\n              </div>\n            ) : !loading ? (\n              /* ONLY TWO BUTTONS IN THE AUTH AREA AS ORDERED */\n              <div className=\"flex items-center gap-2\">\n                <button\n                  type=\"button\"\n                  onClick={() => openAuthModal(\"login\")}\n                  className=\"inline-flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 hover:text-blue-600 dark:hover:text-blue-400 bg-slate-100/80 dark:bg-slate-800 hover:bg-slate-200/70 dark:hover:bg-slate-700 rounded-xl transition cursor-pointer\"\n                >\n                  <LogIn className=\"w-4 h-4\" />\n                  <span>{t.nav.login}</span>\n                </button>\n\n                <button\n                  type=\"button\"\n                  onClick={() => openAuthModal(\"register\")}\n                  className=\"inline-flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 active:bg-blue-800 rounded-xl shadow-sm shadow-blue-500/20 transition cursor-pointer\"\n                >\n                  <UserPlus className=\"w-4 h-4\" />\n                  <span>{t.nav.register}</span>\n                </button>\n              </div>\n            ) : null}\n          </div>\n\n          {/* Mobile Controls */}\n          <div className=\"flex items-center gap-2 md:hidden\">\n            {/* Compact Language Pill */}\n            <button\n              type=\"button\"\n              onClick={() =>\n                setLocale(locale === \"ar\" ? \"fr\" : locale === \"fr\" ? \"en\" : \"ar\")\n              }\n              className=\"px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-extrabold text-slate-700 dark:text-slate-200\"\n            >\n              {locale.toUpperCase()}\n            </button>\n\n            {/* Compact Theme Pill */}\n            <button\n              type=\"button\"\n              onClick={toggleTheme}\n              className=\"p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-700 dark:text-amber-300\"\n            >\n              {theme === \"light\" ? <Moon className=\"w-4 h-4\" /> : <Sun className=\"w-4 h-4\" />}\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}\n              className=\"p-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition\"\n              aria-label=\"Menu\"\n            >\n              {mobileMenuOpen ? <X className=\"w-6 h-6\" /> : <Menu className=\"w-6 h-6\" />}\n            </button>\n          </div>\n        </div>\n      </div>\n\n      {/* Mobile Drawer */}\n      {mobileMenuOpen && (\n        <div className=\"md:hidden border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 px-4 pt-3 pb-6 space-y-3\">\n          <nav className=\"flex flex-col gap-1\">\n            {navLinks.map((link) => (\n              <Link\n                key={link.href}\n                href={link.href}\n                onClick={() => setMobileMenuOpen(false)}\n                className=\"px-3 py-2 rounded-lg text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800\"\n              >\n                {link.label}\n              </Link>\n            ))}\n          </nav>\n\n          <div className=\"pt-3 border-t border-slate-100 dark:border-slate-800 space-y-2\">\n            {user ? (\n              <>\n                <Link\n                  href=\"/profile\"\n                  onClick={() => setMobileMenuOpen(false)}\n                  className=\"block px-3 py-2 rounded-lg text-sm font-bold text-slate-800 dark:text-slate-100\"\n                >\n                  {t.nav.profile} ({user.name})\n                </Link>\n                {user.role !== \"STUDENT\" && (\n                  <Link\n                    href=\"/upload\"\n                    onClick={() => setMobileMenuOpen(false)}\n                    className=\"block px-3 py-2 rounded-lg text-sm font-bold text-blue-600 dark:text-blue-400\"\n                  >\n                    + {t.nav.upload}\n                  </Link>\n                )}\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    handleSignOut();\n                  }}\n                  className=\"w-full text-start px-3 py-2 text-sm font-bold text-red-600 rounded-lg\"\n                >\n                  {t.nav.logout}\n                </button>\n              </>\n            ) : (\n              <div className=\"grid grid-cols-2 gap-2 pt-1\">\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    openAuthModal(\"login\");\n                  }}\n                  className=\"py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 bg-slate-100 dark:bg-slate-800 rounded-xl\"\n                >\n                  {t.nav.login}\n                </button>\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    openAuthModal(\"register\");\n                  }}\n                  className=\"py-2.5 text-sm font-bold text-white bg-blue-600 rounded-xl\"\n                >\n                  {t.nav.register}\n                </button>\n              </div>\n            )}\n          </div>\n        </div>\n      )}\n    </header>\n  );\n}\n",
  "src/app/globals.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  :root {\n    --background: 210 40% 98%;\n    --foreground: 222.2 84% 4.9%;\n  }\n\n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n  }\n\n  * {\n    box-sizing: border-box;\n  }\n\n  body {\n    background-color: #f8fafc;\n    color: #0f172a;\n    font-family: var(--font-cairo), system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    transition: background-color 0.2s ease, color 0.2s ease;\n  }\n\n  html.dark body {\n    background-color: #020617;\n    color: #f8fafc;\n  }\n}\n\n/* Automatic Dark Mode Surface Overrides for Existing Components */\nhtml.dark .bg-white {\n  background-color: #0f172a !important;\n}\n\nhtml.dark .bg-slate-50 {\n  background-color: #1e293b !important;\n}\n\nhtml.dark .text-slate-900 {\n  color: #f8fafc !important;\n}\n\nhtml.dark .text-slate-800 {\n  color: #f1f5f9 !important;\n}\n\nhtml.dark .text-slate-700 {\n  color: #cbd5e1 !important;\n}\n\nhtml.dark .text-slate-600 {\n  color: #94a3b8 !important;\n}\n\nhtml.dark .border-slate-200,\nhtml.dark .border-slate-100,\nhtml.dark .border-slate-300 {\n  border-color: #1e293b !important;\n}\n\n/* Custom scrollbars */\n::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n::-webkit-scrollbar-track {\n  background: #f1f5f9;\n}\n\nhtml.dark ::-webkit-scrollbar-track {\n  background: #0f172a;\n}\n\n::-webkit-scrollbar-thumb {\n  background: #cbd5e1;\n  border-radius: 9999px;\n}\n\nhtml.dark ::-webkit-scrollbar-thumb {\n  background: #334155;\n}\n",
  "src/app/layout.tsx": "import type { Metadata } from \"next\";\nimport { Cairo } from \"next/font/google\";\nimport Navbar from \"@/components/layout/Navbar\";\nimport AuthRoleModal from \"@/components/auth/AuthRoleModal\";\nimport { AppPreferencesProvider } from \"@/context/AppPreferencesContext\";\nimport \"./globals.css\";\n\nconst cairo = Cairo({\n  subsets: [\"arabic\", \"latin\"],\n  weight: [\"300\", \"400\", \"500\", \"600\", \"700\", \"800\"],\n  variable: \"--font-cairo\",\n  display: \"swap\",\n});\n\nexport const metadata: Metadata = {\n  title: \"بنك أنشطة المعلم | Teacher's Activity Bank\",\n  description:\n    \"المنصة الشاملة للمؤسسات التربوية، المتفقدين، المعلمين، والتلاميذ لتصفح، مشاركة، معاينة، وتحميل أوراق العمل والأنشطة المدرسية.\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"ar\" dir=\"rtl\" className={cairo.variable} suppressHydrationWarning>\n      <body className=\"min-h-screen flex flex-col bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-50 font-cairo\">\n        <AppPreferencesProvider>\n          {/* Global Top Navbar with Theme, Language, and 2-Button Auth */}\n          <Navbar />\n\n          {/* Global Full-Screen 4-Role Selection Overlay */}\n          <AuthRoleModal />\n\n          {/* Main Content Area */}\n          <main className=\"flex-1\">{children}</main>\n\n          {/* Global Footer */}\n          <footer className=\"bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 py-10 mt-16\">\n            <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n              <div className=\"pt-2 flex flex-col sm:flex-row items-center justify-between text-xs text-slate-400 gap-3\">\n                <p>© {new Date().getFullYear()} بنك أنشطة المعلم — Teacher&apos;s Activity Bank.</p>\n                <p>منصة تعليمية تدعم المؤسسات، المتفقدين، المعلمين، والتلاميذ (AR / FR / EN).</p>\n              </div>\n            </div>\n          </footer>\n        </AppPreferencesProvider>\n      </body>\n    </html>\n  );\n}\n",
  "src/app/(auth)/login/page.tsx": "\"use client\";\n\n/**\n * Upgraded Multi-Role Login Page (v2.0)\n *\n * - Displays the Full-Screen 4-Option Role Selector if no `?role=` is chosen yet,\n *   or allows switching between the 4 account roles (INSTITUTION, INSPECTOR, TEACHER, STUDENT) at any time.\n * - Fully localized in Arabic, French, and English + supports Dark Mode.\n */\n\nimport React, { useState, useEffect, FormEvent, Suspense } from \"react\";\nimport { useRouter, useSearchParams } from \"next/navigation\";\nimport Link from \"next/link\";\nimport { Mail, Lock, Loader2, AlertCircle, RefreshCw } from \"lucide-react\";\nimport { createSupabaseBrowserClient } from \"@/lib/supabase/client\";\nimport { signInSchema } from \"@/lib/validators/auth\";\nimport { useAppPreferences } from \"@/context/AppPreferencesContext\";\nimport { ROLE_VISUAL_CARDS } from \"@/components/auth/AuthRoleModal\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nfunction LoginContent() {\n  const router = useRouter();\n  const searchParams = useSearchParams();\n  const redirectTo = searchParams?.get(\"redirectTo\") || \"/\";\n  const roleParam = searchParams?.get(\"role\")?.toUpperCase() as AccountRoleOption | undefined;\n\n  const { t } = useAppPreferences();\n\n  const [selectedRole, setSelectedRole] = useState<AccountRoleOption | null>(\n    roleParam && [\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"].includes(roleParam)\n      ? roleParam\n      : null\n  );\n\n  useEffect(() => {\n    if (roleParam && [\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"].includes(roleParam)) {\n      setSelectedRole(roleParam);\n    }\n  }, [roleParam]);\n\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const handleLogin = async (e: FormEvent) => {\n    e.preventDefault();\n    setError(null);\n\n    const parsed = signInSchema.safeParse({\n      email,\n      password,\n      role: selectedRole || \"TEACHER\",\n    });\n\n    if (!parsed.success) {\n      setError(parsed.error.errors[0]?.message || \"البيانات المدخلة غير صحيحة\");\n      return;\n    }\n\n    try {\n      setLoading(true);\n      const supabase = createSupabaseBrowserClient();\n      const { error: authError } = await supabase.auth.signInWithPassword({\n        email: parsed.data.email,\n        password: parsed.data.password,\n      });\n\n      if (authError) {\n        setError(\"البريد الإلكتروني أو كلمة المرور غير صحيحة\");\n        return;\n      }\n\n      router.push(redirectTo);\n      router.refresh();\n    } catch {\n      setError(\"حدث خطأ أثناء تسجيل الدخول\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleGoogleLogin = async () => {\n    const supabase = createSupabaseBrowserClient();\n    await supabase.auth.signInWithOAuth({\n      provider: \"google\",\n      options: {\n        redirectTo: `${window.location.origin}/api/auth/callback?next=${encodeURIComponent(redirectTo)}`,\n      },\n    });\n  };\n\n  // Step 1: Full-Screen 4-Option Role Selector if user hasn't picked a role yet\n  if (!selectedRole) {\n    return (\n      <div className=\"max-w-7xl w-full mx-auto py-8 px-4 space-y-8\" dir={t.dir}>\n        <div className=\"text-center space-y-3 max-w-2xl mx-auto\">\n          <h1 className=\"text-3xl sm:text-4xl font-black text-slate-900 dark:text-white\">\n            {t.authModal.loginTitle}\n          </h1>\n          <p className=\"text-sm sm:text-base text-slate-500 dark:text-slate-400\">\n            {t.authModal.loginSubtitle}\n          </p>\n        </div>\n\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5\">\n          {ROLE_VISUAL_CARDS.map((card) => {\n            const Icon = card.icon;\n            const roleText = t.roles[card.role];\n            return (\n              <button\n                key={card.role}\n                type=\"button\"\n                onClick={() => setSelectedRole(card.role)}\n                className={`group relative text-start bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 ${card.borderHover} rounded-3xl p-6 shadow-md hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 flex flex-col justify-between cursor-pointer overflow-hidden`}\n              >\n                <div className={`absolute top-0 inset-x-0 h-2 bg-gradient-to-r ${card.gradient}`} />\n                <div className=\"space-y-4 pt-2\">\n                  <div className=\"flex items-center justify-between\">\n                    <span className={`px-3 py-1 rounded-full text-[11px] font-extrabold border ${card.badgeStyle}`}>\n                      {roleText.badge}\n                    </span>\n                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${card.iconBg}`}>\n                      <Icon className=\"w-6 h-6\" />\n                    </div>\n                  </div>\n                  <h3 className=\"text-xl font-black text-slate-900 dark:text-white\">\n                    {roleText.title}\n                  </h3>\n                  <p className=\"text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                    {roleText.subtitle}\n                  </p>\n                </div>\n                <div className=\"pt-5 mt-5 border-t border-slate-100 dark:border-slate-800 text-xs font-extrabold text-blue-600 dark:text-blue-400\">\n                  {t.authModal.continueBtn} →\n                </div>\n              </button>\n            );\n          })}\n        </div>\n\n        <p className=\"text-center text-sm text-slate-600 dark:text-slate-400\">\n          <Link href=\"/register\" className=\"text-blue-600 dark:text-blue-400 font-bold hover:underline\">\n            {t.authModal.switchToRegister}\n          </Link>\n        </p>\n      </div>\n    );\n  }\n\n  const activeCard = ROLE_VISUAL_CARDS.find((c) => c.role === selectedRole) || ROLE_VISUAL_CARDS[2];\n  const ActiveIcon = activeCard.icon;\n  const roleCopy = t.roles[selectedRole];\n\n  return (\n    <div className=\"w-full max-w-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-lg\" dir={t.dir}>\n      {/* Interactive Role Switcher Pills inside the Login Card */}\n      <div className=\"mb-6\">\n        <div className=\"flex items-center justify-between mb-2\">\n          <span className=\"text-xs font-bold text-slate-500 dark:text-slate-400\">\n            {t.authModal.changeRoleBtn}:\n          </span>\n          <button\n            type=\"button\"\n            onClick={() => setSelectedRole(null)}\n            className=\"text-xs font-bold text-blue-600 hover:underline inline-flex items-center gap-1 cursor-pointer\"\n          >\n            <RefreshCw className=\"w-3 h-3\" />\n            <span>عرض البطاقات الأربع</span>\n          </button>\n        </div>\n        <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-2\">\n          {ROLE_VISUAL_CARDS.map((card) => {\n            const Icon = card.icon;\n            const active = selectedRole === card.role;\n            return (\n              <button\n                key={card.role}\n                type=\"button\"\n                onClick={() => setSelectedRole(card.role)}\n                className={`flex items-center justify-center gap-1.5 py-2 px-2.5 rounded-xl text-xs font-bold border transition cursor-pointer ${\n                  active\n                    ? \"bg-blue-600 text-white border-blue-600 shadow-sm\"\n                    : \"bg-slate-50 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:bg-slate-100\"\n                }`}\n              >\n                <Icon className=\"w-3.5 h-3.5 shrink-0\" />\n                <span className=\"truncate\">{t.roles[card.role].title.replace(\"حساب \", \"\").replace(\"Espace \", \"\")}</span>\n              </button>\n            );\n          })}\n        </div>\n      </div>\n\n      <div className=\"flex flex-col items-center text-center mb-6\">\n        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 shadow-md ${activeCard.iconBg}`}>\n          <ActiveIcon className=\"w-7 h-7\" />\n        </div>\n        <span className={`px-3 py-0.5 rounded-full text-[11px] font-bold border mb-2 ${activeCard.badgeStyle}`}>\n          {roleCopy.badge}\n        </span>\n        <h1 className=\"text-2xl font-black text-slate-900 dark:text-white\">\n          {t.nav.login} — {roleCopy.title}\n        </h1>\n        <p className=\"text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1\">\n          {roleCopy.subtitle}\n        </p>\n      </div>\n\n      {error && (\n        <div className=\"mb-5 p-3.5 rounded-xl bg-red-50 border border-red-200 text-red-700 text-xs flex items-center gap-2\">\n          <AlertCircle className=\"w-4 h-4 shrink-0\" />\n          <span>{error}</span>\n        </div>\n      )}\n\n      <form onSubmit={handleLogin} className=\"space-y-4\">\n        <div>\n          <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n            {t.authForm.emailLabel}\n          </label>\n          <div className=\"relative\">\n            <Mail className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n            <input\n              type=\"email\"\n              required\n              value={email}\n              onChange={(e) => setEmail(e.target.value)}\n              placeholder=\"user@education.edu\"\n              className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n            />\n          </div>\n        </div>\n\n        <div>\n          <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n            {t.authForm.passwordLabel}\n          </label>\n          <div className=\"relative\">\n            <Lock className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n            <input\n              type=\"password\"\n              required\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              placeholder=\"••••••••\"\n              className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n            />\n          </div>\n        </div>\n\n        <button\n          type=\"submit\"\n          disabled={loading}\n          className=\"w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold text-sm flex items-center justify-center gap-2 transition cursor-pointer shadow-sm\"\n        >\n          {loading && <Loader2 className=\"w-4 h-4 animate-spin\" />}\n          <span>{t.authForm.submitLogin}</span>\n        </button>\n      </form>\n\n      <div className=\"my-5 flex items-center gap-3\">\n        <div className=\"h-px bg-slate-200 dark:bg-slate-700 flex-1\" />\n        <span className=\"text-xs text-slate-400\">{t.authForm.orDivider}</span>\n        <div className=\"h-px bg-slate-200 dark:bg-slate-700 flex-1\" />\n      </div>\n\n      <button\n        type=\"button\"\n        onClick={handleGoogleLogin}\n        className=\"w-full py-2.5 px-4 rounded-xl border border-slate-300 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-200 font-semibold text-sm flex items-center justify-center gap-2 transition cursor-pointer\"\n      >\n        <span>{t.authForm.googleContinue}</span>\n      </button>\n\n      <p className=\"text-center text-xs text-slate-600 dark:text-slate-400 mt-6\">\n        <Link\n          href={`/register?role=${selectedRole}`}\n          className=\"text-blue-600 dark:text-blue-400 font-bold hover:underline\"\n        >\n          {t.authModal.switchToRegister}\n        </Link>\n      </p>\n    </div>\n  );\n}\n\nexport default function LoginPage() {\n  return (\n    <main className=\"min-h-[82vh] flex items-center justify-center px-4 py-10\">\n      <Suspense\n        fallback={\n          <div className=\"w-full max-w-md bg-white border border-slate-200 rounded-2xl p-12 flex flex-col items-center justify-center gap-3\">\n            <Loader2 className=\"w-8 h-8 text-blue-600 animate-spin\" />\n          </div>\n        }\n      >\n        <LoginContent />\n      </Suspense>\n    </main>\n  );\n}\n",
  "src/app/(auth)/register/page.tsx": "\"use client\";\n\n/**\n * Upgraded Multi-Role Registration Page (v2.0)\n *\n * Allows the user to choose or switch between the 4 account types inside the registration flow:\n * 1. INSTITUTION (مؤسسة تربوية)\n * 2. INSPECTOR (متفقد تربوي)\n * 3. TEACHER (معلم)\n * 4. STUDENT (تلميذ)\n */\n\nimport React, { useState, useEffect, FormEvent, Suspense } from \"react\";\nimport { useRouter, useSearchParams } from \"next/navigation\";\nimport Link from \"next/link\";\nimport {\n  User,\n  Mail,\n  Lock,\n  Building2,\n  Loader2,\n  AlertCircle,\n  KeyRound,\n  CheckCircle2,\n} from \"lucide-react\";\nimport { createSupabaseBrowserClient } from \"@/lib/supabase/client\";\nimport { signUpSchema } from \"@/lib/validators/auth\";\nimport { useAppPreferences } from \"@/context/AppPreferencesContext\";\nimport { ROLE_VISUAL_CARDS } from \"@/components/auth/AuthRoleModal\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nfunction RegisterContent() {\n  const router = useRouter();\n  const searchParams = useSearchParams();\n  const roleParam = searchParams?.get(\"role\")?.toUpperCase() as AccountRoleOption | undefined;\n\n  const { t } = useAppPreferences();\n\n  const [selectedRole, setSelectedRole] = useState<AccountRoleOption>(\n    roleParam && [\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"].includes(roleParam)\n      ? roleParam\n      : \"TEACHER\"\n  );\n\n  useEffect(() => {\n    if (roleParam && [\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"].includes(roleParam)) {\n      setSelectedRole(roleParam);\n    }\n  }, [roleParam]);\n\n  const [name, setName] = useState(\"\");\n  const [school, setSchool] = useState(\"\");\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const activeCard =\n    ROLE_VISUAL_CARDS.find((c) => c.role === selectedRole) || ROLE_VISUAL_CARDS[2];\n  const ActiveIcon = activeCard.icon;\n  const roleCopy = t.roles[selectedRole];\n\n  const handleRegister = async (e: FormEvent) => {\n    e.preventDefault();\n    setError(null);\n\n    if ((selectedRole === \"INSTITUTION\" || selectedRole === \"INSPECTOR\") && !school.trim()) {\n      setError(roleCopy.orgLabel);\n      return;\n    }\n\n    const parsed = signUpSchema.safeParse({\n      name,\n      email,\n      password,\n      school: school.trim() || undefined,\n      role: selectedRole,\n    });\n\n    if (!parsed.success) {\n      setError(parsed.error.errors[0]?.message || \"يرجى التأكد من صحة البيانات\");\n      return;\n    }\n\n    try {\n      setLoading(true);\n      const supabase = createSupabaseBrowserClient();\n      const { error: signUpError } = await supabase.auth.signUp({\n        email: parsed.data.email,\n        password: parsed.data.password,\n        options: {\n          data: {\n            name: parsed.data.name,\n            school: parsed.data.school,\n            role: selectedRole,\n            inspector_pending: selectedRole === \"INSPECTOR\",\n          },\n        },\n      });\n\n      if (signUpError) {\n        setError(signUpError.message);\n        return;\n      }\n\n      if (selectedRole === \"INSPECTOR\") {\n        router.push(\"/inspector/activate\");\n      } else {\n        router.push(\"/\");\n      }\n      router.refresh();\n    } catch {\n      setError(\"حدث خطأ أثناء إنشاء الحساب\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div className=\"max-w-4xl w-full mx-auto space-y-8\" dir={t.dir}>\n      {/* Top 4-Role Selector Cards inside the Registration Page */}\n      <div className=\"space-y-3 text-center\">\n        <h1 className=\"text-2xl sm:text-3xl font-black text-slate-900 dark:text-white\">\n          {t.authModal.registerTitle}\n        </h1>\n        <p className=\"text-sm text-slate-500 dark:text-slate-400\">\n          {t.authModal.registerSubtitle}\n        </p>\n\n        <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 pt-3\">\n          {ROLE_VISUAL_CARDS.map((card) => {\n            const Icon = card.icon;\n            const isSelected = selectedRole === card.role;\n            const cardText = t.roles[card.role];\n\n            return (\n              <button\n                key={card.role}\n                type=\"button\"\n                onClick={() => setSelectedRole(card.role)}\n                className={`relative text-start p-4 rounded-2xl border-2 transition-all cursor-pointer flex flex-col justify-between gap-2 ${\n                  isSelected\n                    ? \"bg-blue-50/70 dark:bg-blue-950/40 border-blue-600 shadow-md\"\n                    : \"bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 hover:border-slate-300\"\n                }`}\n              >\n                <div className=\"flex items-center justify-between w-full\">\n                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${card.iconBg}`}>\n                    <Icon className=\"w-5 h-5\" />\n                  </div>\n                  {isSelected && <CheckCircle2 className=\"w-5 h-5 text-blue-600\" />}\n                </div>\n                <div>\n                  <div className=\"font-extrabold text-sm text-slate-900 dark:text-white\">\n                    {cardText.title}\n                  </div>\n                  <div className=\"text-[11px] text-slate-500 dark:text-slate-400 line-clamp-2 mt-0.5\">\n                    {cardText.subtitle}\n                  </div>\n                </div>\n              </button>\n            );\n          })}\n        </div>\n      </div>\n\n      {/* Registration Form Card */}\n      <div className=\"max-w-xl mx-auto bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-lg\">\n        <div className=\"flex items-center gap-3.5 pb-5 mb-6 border-b border-slate-100 dark:border-slate-800\">\n          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-md ${activeCard.iconBg}`}>\n            <ActiveIcon className=\"w-6 h-6\" />\n          </div>\n          <div>\n            <span className={`inline-block px-2.5 py-0.5 rounded-full text-[10px] font-bold border mb-1 ${activeCard.badgeStyle}`}>\n              {roleCopy.badge}\n            </span>\n            <h2 className=\"text-xl font-black text-slate-900 dark:text-white\">\n              {roleCopy.title}\n            </h2>\n          </div>\n        </div>\n\n        {selectedRole === \"INSPECTOR\" && (\n          <div className=\"mb-5 p-3.5 rounded-xl bg-amber-50 dark:bg-amber-950/50 border border-amber-200 dark:border-amber-800 text-amber-900 dark:text-amber-200 text-xs font-semibold leading-relaxed\">\n            {t.authForm.inspectorNote}\n          </div>\n        )}\n\n        {error && (\n          <div className=\"mb-5 p-3.5 rounded-xl bg-red-50 border border-red-200 text-red-700 text-xs flex items-center gap-2\">\n            <AlertCircle className=\"w-4 h-4 shrink-0\" />\n            <span>{error}</span>\n          </div>\n        )}\n\n        <form onSubmit={handleRegister} className=\"space-y-4\">\n          <div>\n            <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n              {roleCopy.nameLabel}\n            </label>\n            <div className=\"relative\">\n              <User className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n              <input\n                type=\"text\"\n                required\n                value={name}\n                onChange={(e) => setName(e.target.value)}\n                placeholder={roleCopy.namePlaceholder}\n                className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n              {roleCopy.orgLabel}\n            </label>\n            <div className=\"relative\">\n              <Building2 className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n              <input\n                type=\"text\"\n                required={selectedRole === \"INSTITUTION\" || selectedRole === \"INSPECTOR\"}\n                value={school}\n                onChange={(e) => setSchool(e.target.value)}\n                placeholder={roleCopy.orgPlaceholder}\n                className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n              {t.authForm.emailLabel}\n            </label>\n            <div className=\"relative\">\n              <Mail className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n              <input\n                type=\"email\"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                placeholder=\"name@education.edu\"\n                className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n              {t.authForm.passwordLabel} ({t.authForm.passwordHint})\n            </label>\n            <div className=\"relative\">\n              <Lock className=\"w-4 h-4 text-slate-400 absolute start-3.5 top-3.5\" />\n              <input\n                type=\"password\"\n                required\n                minLength={8}\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                placeholder=\"••••••••\"\n                className=\"w-full ps-10 pe-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n          </div>\n\n          <button\n            type=\"submit\"\n            disabled={loading}\n            className=\"w-full py-3.5 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold text-sm flex items-center justify-center gap-2 transition cursor-pointer shadow-sm\"\n          >\n            {loading && <Loader2 className=\"w-4 h-4 animate-spin\" />}\n            <span>\n              {t.authForm.submitRegister} ({roleCopy.title})\n            </span>\n          </button>\n        </form>\n\n        <div className=\"mt-6 pt-4 border-t border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row items-center justify-between gap-2 text-xs text-slate-600 dark:text-slate-400\">\n          <Link\n            href={`/login?role=${selectedRole}`}\n            className=\"text-blue-600 dark:text-blue-400 font-bold hover:underline\"\n          >\n            {t.authModal.switchToLogin}\n          </Link>\n\n          {selectedRole === \"INSPECTOR\" && (\n            <Link\n              href=\"/inspector/activate\"\n              className=\"text-amber-700 dark:text-amber-400 font-bold hover:underline inline-flex items-center gap-1\"\n            >\n              <KeyRound className=\"w-3.5 h-3.5\" />\n              <span>{t.authForm.activateCodeLink}</span>\n            </Link>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport default function RegisterPage() {\n  return (\n    <main className=\"min-h-[85vh] flex items-center justify-center px-4 py-10\">\n      <Suspense\n        fallback={\n          <div className=\"w-full max-w-md bg-white border border-slate-200 rounded-2xl p-12 flex flex-col items-center justify-center gap-3\">\n            <Loader2 className=\"w-8 h-8 text-blue-600 animate-spin\" />\n          </div>\n        }\n      >\n        <RegisterContent />\n      </Suspense>\n    </main>\n  );\n}\n"
};

const rootDir = process.cwd();
console.log("🚀 Applying Project Manager Directives & Architectural Upgrades in:", rootDir);

let writtenCount = 0;
for (const [relPath, content] of Object.entries(files)) {
  const fullPath = path.join(rootDir, relPath);
  const dir = path.dirname(fullPath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(fullPath, content, "utf-8");
  console.log("  ✅ Updated:", relPath);
  writtenCount++;
}

// Also update scripts/generate-handover.mjs if present so new files are tracked in future handovers
const handoverScriptPath = path.join(rootDir, "scripts/generate-handover.mjs");
if (fs.existsSync(handoverScriptPath)) {
  let hs = fs.readFileSync(handoverScriptPath, "utf-8");
  if (!hs.includes("src/context/AppPreferencesContext.tsx")) {
    hs = hs.replace(
      '"src/components/layout/Navbar.tsx",',
      '"src/context/AppPreferencesContext.tsx",\n  "src/components/auth/AuthRoleModal.tsx",\n  "src/components/layout/Navbar.tsx",'
    );
    fs.writeFileSync(handoverScriptPath, hs, "utf-8");
    console.log("  ✅ Registered new files in scripts/generate-handover.mjs");
  }
}

console.log(`\n🎉 Successfully applied ${writtenCount} core architectural & UI upgrades!`);
